look.customCSS:
/* ───── 洛可可墨绿 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,") 0 0/48px 64px,radial-gradient(ellipse at 50% 30%,#245447,#183C34 80%) !important}
[data-wk="body"]{background:transparent !important}
[data-wk="chat"] *{font-family:"Songti SC","Noto Serif SC","STSong",serif !important}

/* 顶栏：奶油底，下沿一道橘红边，再垂一条金涡卷花边带、正中一枚洛可可饰 */
[data-wk="chathead"]{background:#F4EAD2 !important;border-bottom:none !important;box-shadow:0 5px 0 #D5603A,0 7px 0 #A8442A !important;position:relative !important;overflow:visible !important;gap:6px !important;z-index:5 !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:calc(100% + 8px) !important;height:20px !important;background:url("data:image/svg+xml;base64,") center top/56px 28px no-repeat,url("data:image/svg+xml;base64,") 0 0/40px 20px repeat-x !important;pointer-events:none !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:28px !important}
[data-wk="body"]{padding-top:14px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#3B2E22 !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:700 !important;letter-spacing:.12em !important;white-space:nowrap !important}
[data-wk="headname"] > [data-wk="headink"] > span{flex:none !important}
[data-wk="headname"] > [data-wk="headink"]::after{content:"mon ange" !important;flex:0 1 auto !important;min-width:0 !important;overflow:hidden !important;margin-left:8px !important;font:italic 400 13px/1 Georgia,"Times New Roman",serif !important;letter-spacing:.02em !important;color:#D5603A !important}
[data-wk="headdim"]{color:#8C7F66 !important;white-space:nowrap !important;letter-spacing:.12em !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#3B2E22 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:34px !important;min-width:34px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆的，套一面金珠圈镜框，顶上洛可可饰、底下一对涡卷 */
button[data-wk="avatar"],span[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:50% !important;box-shadow:none !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:50% !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;left:-25% !important;right:-25% !important;top:-38% !important;bottom:-38% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;border:none !important;border-radius:0 !important;z-index:2 !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"]){position:relative !important;overflow:visible !important}
[data-wk="chathead"] button:has(> img[data-wk="avatar"])::before{content:"" !important;position:absolute !important;left:-4px !important;top:50% !important;width:44px !important;height:44px !important;margin-top:-22px !important;border-radius:50% !important;box-shadow:0 0 0 3px #D8B26A,0 0 0 4.5px #9C7A3C !important;background:radial-gradient(circle,transparent 60%,transparent 61%) !important;pointer-events:none !important;z-index:2 !important}
[data-wk="chathead"] img[data-wk="avatar"]{border-radius:50% !important}

/* 气泡：圆角牌，金细边；顶上正中一枚洛可可饰，右上、左下各卷一道金涡卷 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:14px !important;letter-spacing:.06em !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"]::before{content:"" !important;position:absolute !important;left:50% !important;top:-13px !important;width:40px !important;height:20px !important;margin-left:-20px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;pointer-events:none !important;border:none !important;transform:none !important;right:auto !important;bottom:auto !important}
[data-wk="bubble"][data-kind="text"]::after{content:"" !important;position:absolute !important;inset:-12px !important;background:url("data:image/svg+xml;base64,") right top/18px 18px no-repeat,url("data:image/svg+xml;base64,") left bottom/18px 18px no-repeat !important;pointer-events:none !important;border:none !important;transform:none !important;width:auto !important;height:auto !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(180deg,#DC6A44,#D5603A) !important;color:#F4EAD2 !important;border:none !important;box-shadow:0 0 0 2px #D8B26A,0 0 0 3px #9C7A3C,0 4px 0 3px rgba(0,0,0,.18) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#F4EAD2 !important;color:#3B2E22 !important;border:none !important;box-shadow:0 0 0 2px #D8B26A,0 0 0 3px #9C7A3C,0 4px 0 3px rgba(0,0,0,.18) !important}
[data-first="0"] [data-wk="bubble"][data-kind="text"]::before{content:none !important}

/* 时间：一枚椭圆徽框，顶上洛可可饰、两侧涡卷 */
[data-wk="time"]{display:flex !important;justify-content:center !important;margin-top:10px !important}
[data-wk="time"] > span{position:relative !important;display:inline-flex !important;align-items:center !important;justify-content:center !important;min-width:150px !important;height:34px !important;padding:6px 34px 0 !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;border:none !important;box-shadow:none !important;color:#3B2E22 !important;letter-spacing:.15em !important;font-size:12.5px !important}
[data-wk="time"] > span::before{content:"" !important;position:absolute !important;left:50% !important;top:-14px !important;width:40px !important;height:20px !important;margin-left:-20px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="time"] > span::after{content:"" !important;position:absolute !important;left:-14px !important;right:-14px !important;top:6px !important;height:26px !important;background:url("data:image/svg+xml;base64,") left center/20px 20px no-repeat,url("data:image/svg+xml;base64,") right center/20px 20px no-repeat !important}
/* 已送达＝后面一颗橘红涡纹；已读＝前面一颗橘红圆点 */
[data-wk="meta"]{color:#C9BFA6 !important;font-size:10.5px !important;letter-spacing:.12em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"][data-read="0"]::after{content:"" !important;width:12px !important;height:12px !important;flex:none !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::before{content:"" !important;width:11px !important;height:11px !important;flex:none !important;order:-1 !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAyMCc+PGNpcmNsZSBjeD0nMTAnIGN5PScxMCcgcj0nOCcgZmlsbD0nI0Q1NjAzQScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#F4EAD2 !important;border:none !important;box-shadow:0 0 0 2px #D8B26A !important;border-radius:14px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#D5603A !important}
[data-wk="name"]{color:#C9BFA6 !important}

/* 动描：一卷展开的羊皮纸条——两头卷起，中间淡奶油底、墨绿斜体字 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{position:relative !important;display:block !important;background:linear-gradient(90deg,#EADBB8,#F4EAD2 12%,#F4EAD2 88%,#EADBB8) !important;border:none !important;border-top:1px solid #D8B26A !important;border-bottom:1px solid #D8B26A !important;border-radius:0 !important;box-shadow:0 4px 10px rgba(0,0,0,.25) !important;color:#1F4A40 !important;font-style:italic !important;font-size:13px !important;line-height:1.8 !important;letter-spacing:.06em !important;padding:12px 30px !important;margin:0 14px !important;overflow:visible !important}
[data-wk="narrink"]::before,[data-wk="narrink"]::after{content:"" !important;position:absolute !important;top:-4px !important;bottom:-4px !important;width:14px !important;background:linear-gradient(90deg,#9C7A3C,#D8B26A 40%,#EADBB8 60%,#9C7A3C) !important;border-radius:7px !important;box-shadow:0 2px 4px rgba(0,0,0,.3) !important}
[data-wk="narrink"]::before{left:-8px !important}
[data-wk="narrink"]::after{right:-8px !important}
/* 系统提示：一行奶油小字，两头各一道小涡卷 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#C9BFA6 !important;font-size:11.5px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnotetext"]::before{content:"" !important;display:inline-block !important;width:13px !important;height:13px !important;margin-right:6px !important;vertical-align:-2px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="sysnoteclose"]{color:#C9BFA6 !important}

/* 底栏：奶油底，上沿一道墨绿边＋一条涡卷花边带；右边是一枚大的橘红发送章，戴金珠圈、顶洛可可饰 */
[data-wk="composer"]{background:#F4EAD2 !important;border-top:none !important;box-shadow:0 -4px 0 #2E6355 !important;position:relative !important;overflow:visible !important;align-items:center !important;gap:10px !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:calc(100% + 4px) !important;height:20px !important;background:url("data:image/svg+xml;base64,") 0 0/40px 20px repeat-x !important;transform:scaleY(-1) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:#FBF5E6 !important;border:1.6px solid #D8B26A !important;border-radius:999px !important;color:#3B2E22 !important;box-shadow:inset 0 0 0 3px #FBF5E6,inset 0 0 0 4px rgba(156,122,60,.4) !important}
[data-wk="chatinput"]::placeholder{color:#A89B80 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatreply"]{width:36px !important;min-width:36px !important;height:36px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:54px !important;min-width:54px !important;height:56px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important;margin-top:-10px !important;order:9 !important}
/* 参考图里回复在左、发送在最右，照图挪 */
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.9) !important}
[data-wk="chatpanel"]{background:#F4EAD2 !important;border-top:2px solid #D8B26A !important}
